+package com.example.contact;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps the sent messages in memory for the lifetime of the application.
+ */
+@Service
+public class MessageService {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void send(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    /** Returns the sent messages, newest first. */
+    public synchronized List<ContactMessage> findAll() {
+        return List.copyOf(messages);
+    }
+}
